from pathlib import Path
import json, html

ROOT = Path(__file__).parent
manifest = json.loads((ROOT/'components.schema.json').read_text())
(ROOT/'catalog-data.js').write_text('window.CG_CATALOG = '+json.dumps(manifest,ensure_ascii=False)+';\n')

def component(name):
    return f'<div class="doc-component-name">CG/{name}<button class="inspect" data-inspect="CG/{name}">Inspecionar</button></div>'
def header(n,title,desc):
    return f'<div class="sheet-head"><div><div class="sheet-kicker">Cabanha Grandi / Biblioteca de interface</div><h2>{title}</h2><p class="sheet-intro">{desc}</p></div><span class="sheet-number">{n}</span></div>'
def sheet(n,name,content):
    return f'<section class="sheet" id="s{n}" data-frame="{n} / {name}">{content}</section>'
def table(headers,rows):
    return '<table class="doc-table"><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def button(label='Consultar este animal',variant='primary',state='default'):
    return f'<button class="cg-button" data-variant="{variant}" data-state="{state}" '+('disabled' if state=='disabled' else 'data-demo="Ação demonstrativa: nenhum contato externo foi iniciado."')+'>'+label+'</button>'

nav=[('00','Visão geral'),('01','Cores e tokens'),('02','Tipo e layout'),('03','Ações e estados'),('04','Cards e conteúdo'),('05','Navegação'),('06','Página e seções'),('07','Para desenvolver')]
out='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cabanha Grandi — Dorper em Foco · Design System 1.0</title><link rel="stylesheet" href="document.css"></head><body>
<header class="doc-bar"><div class="doc-bar__brand"><span class="doc-mark">G</span><span>Cabanha Grandi <span class="doc-bar__meta">/ Dorper em Foco</span></span></div><div class="doc-row"><span class="doc-bar__meta">Design System · v1.0 · PT-BR</span> <button onclick="window.print()">Imprimir / PDF</button></div></header>
<nav class="doc-nav" aria-label="Páginas do documento"><div class="doc-nav-label">PÁGINAS</div>'''
out+=''.join(f'<a href="#s{n}"><span>{n}</span>{name}</a>' for n,name in nav)
out+='''<p class="doc-nav__note">Documento de design em HTML.<br>Componentes inspecionáveis e tokens reutilizáveis.<br><br>Sem dependência de conexão com o Figma.</p></nav><main class="doc-main">'''
out+='''<section class="sheet doc-cover" id="s00" data-frame="00 / Capa · Direção aprovada"><div class="doc-cover-top"><div class="doc-cover-heading"><span class="cg-label cg-muted">CABANHA GRANDI / DESIGN SYSTEM 1.0</span><div class="doc-palette-line"><i style="background:#770D17"></i><i style="background:#FFFFFF"></i><i style="background:#191717"></i></div></div><h1 class="doc-cover-title">Dorper em Foco.<br><em>Da identidade ao código.</em></h1><p class="sheet-intro">Uma biblioteca de interface para contar a história da família Grandi com clareza, presença e consistência.</p></div><div class="doc-cover-hero"><div><p class="cg-label" style="margin-bottom:16px;color:#F0D6D9">NOVA PRATA · RIO GRANDE DO SUL</p><h2>A força da<br>nossa origem.</h2><p style="margin-top:24px;font-size:12px">Imagem ilustrativa · direção fotográfica</p></div></div><div class="doc-cover-bottom"><div><p class="cg-label">O que este documento entrega</p><p style="margin-top:8px">Tokens, anatomia, variantes, estados e contratos. Exemplos reais em HTML/CSS para orientar qualquer ferramenta de código.</p></div><div><strong>14</strong><p>componentes definidos<br>CG/Component</p></div><div><strong>3</strong><p>faixas responsivas<br>360 → 1440px</p></div></div></section>'''

colors=[('Marca','#770D17','--cg-brand','white'),('Hover','#590911','--cg-brand-hover','white'),('Papel','#FFFFFF','--cg-bg','#191717'),('Superfície','#F5F2F0','--cg-surface','#191717'),('Texto','#191717','--cg-text','white'),('Texto auxiliar','#65565A','--cg-muted','white')]
c=header('01','Cores que organizam.','Vinho para identidade e ação. Branco para respiro. Tons semânticos usados apenas para comunicar estados.')
c+='<div class="doc-grid three">'+''.join(f'<div><div class="doc-swatch" style="background:{he};color:{ink}">{he}</div><div class="doc-color-label">{name}</div><code class="doc-dim">{token}</code></div>' for name,he,token,ink in colors)+'</div><div class="doc-rule"></div>'
c+='<div class="doc-grid"><div class="doc-panel">'+component('StatusBadge')+'<div class="cg-row"><span class="cg-badge" data-status="disponivel">Disponível</span><span class="cg-badge" data-status="reservado">Reservado</span><span class="cg-badge" data-status="vendido">Vendido</span></div><p class="doc-note">Um único status por animal. A cor sempre acompanha um rótulo textual.</p></div><div class="doc-panel"><h3>Contraste sólido verificado</h3>'+table(['Combinação','Razão'],[['Branco / vinho','11,32:1'],['Texto / branco','17,85:1'],['Texto auxiliar / branco','6,93:1']])+'<p class="doc-note">AA para texto normal. Fotografias exigem avaliação do overlay no recorte final.</p></div></div><p class="doc-note">Fonte de verdade: tokens.json → generate-tokens.py → tokens.css. As cores semânticas referenciam primitivas; não duplicar valores em componentes.</p>'
out+=sheet('01','Foundations / Colors',c)

c=header('02','Tipografia e ritmo.','Cormorant Garamond cria a voz editorial. DM Sans mantém a interface direta e legível.')
c+='<div class="doc-grid"><div>'
for title,cls,style,dims in [('A força da nossa origem.','cg-h1','font-size:64px;line-height:1.05','H1 · 80/84 → 44/48'),('Nossa história','cg-h2','','H2 · 48/54 → 34/40'),('Animais em destaque','cg-h3','','H3 · 32/38 → 26/32'),('Conheça a Cabanha Grandi e sua criação de ovinos Dorper.','cg-body','','Corpo · 18/28 → 16/26')]:
 c+=f'<div class="doc-type-row"><div class="{cls}" style="{style}">{title}</div><small>{dims}<br>desktop → mobile</small></div>'
c+='</div><div class="cg-stack"><div class="doc-panel"><h3>Escala de espaçamento</h3><div class="doc-space">'+''.join(f'<div class="doc-space-item"><div style="height:{v}px"></div>{v}</div>' for v in [4,8,12,16,24,32,48,64,96])+'</div><p class="doc-note">Raio: 4px · borda: 1px · ícones: 20/24px · alvo de toque: 48px.</p></div><div class="doc-panel"><h3>Container de 1200px / 12 colunas</h3><div class="doc-grid-demo">'+('<span></span>'*12)+'</div><p class="doc-note">Gutter 24px. Margens de 120px em uma tela de 1440px. Mobile: margem 20px e gutter 16px.</p></div></div></div><div class="doc-rule"></div>'
c+=table(['Regra','Desktop ≥1024','Tablet 768–1023','Mobile <768'],[['Container','min(1200, tela − 64)','tela − 48','tela − 40'],['Colunas / gutter','12 / 24px','8 / 24px','4 / 16px'],['Padding de seção','96px','72px','56px'],['Header mínimo','96px','80px','80px']])
out+=sheet('02','Foundations / Type + Layout',c)

c=header('03','Ações com estados claros.','As variantes compartilham dimensões e comportamento. O estilo comunica a prioridade, não uma função diferente.')+component('Button')
c+='<div class="doc-state-grid"><div></div><div class="state-head doc-caption">Primário</div><div class="state-head doc-caption">Secundário</div><div class="state-head doc-caption">Inverso / fundo vinho</div>'
for state,label in [('default','Default'),('hover','Hover'),('pressed','Pressed'),('focus','Focus visible'),('disabled','Disabled')]:
 c+='<span class="state-label">'+label+'</span>'+button('Fale conosco','primary',state)+button('Nossa história','secondary',state)+'<div style="background:#770D17;padding:12px;border-radius:4px">'+button('Conversar','inverse',state)+'</div>'
c+='</div><div class="doc-rule"></div><div class="doc-grid"><div class="doc-panel">'+component('IconButton')+'<div class="cg-row"><button class="cg-icon-button" aria-label="Abrir menu de demonstração" data-open-demo>☰</button><button class="cg-icon-button" aria-label="Exemplo de fechar" data-demo="Exemplo do botão de fechar.">×</button><button class="cg-icon-button" aria-label="Exemplo de próximo" data-demo="Galeria opcional: não implementada no protótipo.">→</button></div><p class="doc-note">48 × 48px · ícone 24px · nome acessível obrigatório.</p></div><div class="doc-panel"><h3>Anatomia de Button</h3><p class="doc-dim">[padding 24] [ícone opcional] [gap 8] [texto] [padding 24]</p><p class="doc-note">Altura mínima 48px · texto 16/24 · peso 600 · transição 160ms. Focus com anel duplo. Disabled usa atributo nativo; links sem destino são omitidos.</p></div></div>'
out+=sheet('03','Components / Actions',c)

c=header('04','Conteúdo sem ambiguidade.','O card representa um animal confirmado. O estado vazio orienta o visitante quando não há itens publicados.')
c+='<div class="doc-grid"><div>'+component('AnimalCard')+'''<article class="cg-card" id="demo-card"><div class="cg-card__media"><img src="assets/hero-illustrative.png" alt="Ovino ilustrativo usado para demonstrar o card" width="1672" height="941"><span class="cg-image-tag">Demonstração · imagem ilustrativa</span></div><div class="cg-card__body"><span class="cg-badge" data-status="disponivel" id="card-badge">Disponível</span><div><h3 class="cg-h3">Identificação do animal</h3><p class="cg-muted">Categoria · informação confirmada</p></div><p>O conteúdo deste card demonstra a estrutura. Não representa uma oferta real.</p><button class="cg-button" id="card-action" data-demo="Demonstração do CTA; sem número ou animal real.">Consultar este animal</button></div></article><div class="doc-toolbar" aria-label="Estado do card"><button data-card-state="disponivel" aria-pressed="true">Disponível</button><button data-card-state="reservado" aria-pressed="false">Reservado</button><button data-card-state="vendido" aria-pressed="false">Vendido</button></div></div><div class="cg-stack">'''+component('EmptyState')+'''<div class="cg-empty"><span class="cg-label">Animais em destaque</span><h3 class="cg-h3">Disponibilidade por contato.</h3><p>Entre em contato para consultar os animais disponíveis.</p>'''+button('Fale conosco')+'''</div><div class="doc-panel">'''+component('SectionHeading')+'''<div class="cg-section-heading"><span class="cg-label cg-muted">03 / Nossa criação</span><h3 class="cg-h2">Dorper em foco.</h3><p>Uma introdução curta contextualiza a próxima seção.</p></div><p class="doc-note">Eyebrow opcional · título h2 · apoio opcional. Gap interno 16px; gap até conteúdo 32px.</p></div></div></div>'''
c+='<p class="doc-note">Card: imagem 4:3 · corpo 24px · gap 16px · raio 4px. Grade de animais: 3 / 2 / 1 colunas. Reservado e vendido usam “Consultar outros animais”.</p>'
out+=sheet('04','Components / Content',c)

c=header('05','Navegação previsível.','A experiência permanece em uma única página. As âncoras conectam história, propriedade, criação, animais e contato.')
c+='<div class="doc-panel">'+component('Header')+'''<div class="cg-row" style="justify-content:space-between"><a class="cg-brand" href="#s00"><span class="cg-brand__small">CABANHA</span><span class="cg-brand__name">GRANDI</span><span class="cg-brand__note">ASSINATURA PROVISÓRIA</span></a><div class="cg-row" style="font-size:13px"><a href="landing.html#historia">História</a><a href="landing.html#criacao">Criação</a><a href="landing.html#animais">Animais</a></div>'''+button('Fale conosco')+'''</div></div><div class="doc-rule"></div><div class="doc-grid"><div>'''+component('MobileMenu')+'''<div class="mini-menu"><div class="cg-row" style="justify-content:space-between"><span class="cg-h3">Navegação</span><button class="cg-icon-button" data-open-demo aria-label="Testar menu modal">☰</button></div><nav aria-label="Exemplo de links do menu"><a href="landing.html#historia">História</a><a href="landing.html#propriedade">Propriedade</a><a href="landing.html#criacao">Criação</a><a href="landing.html#animais">Animais</a><a href="landing.html#contato">Contato</a></nav></div><p class="doc-note">Clique no ícone para testar o diálogo. Escape fecha; foco retorna ao acionador.</p></div><div class="cg-stack"><div class="doc-panel">'''+component('Brand')+'''<h3>Assinatura e área de proteção</h3><p>Aplicar a logo original aprovada. O texto “GRANDI” neste documento é uma assinatura provisória, não uma nova marca.</p><p class="doc-note">Desktop: caixa até 176 × 64px.<br>Mobile: até 136 × 48px.<br>Preservar proporção; não cortar ou esticar.</p></div><div class="doc-panel">'''+component('Footer')+'''<h3>Três áreas, uma leitura simples</h3><p>Marca · âncoras · localidade / copyright.</p><p class="doc-note">Padding vertical 40px. Mobile em coluna, gap 24px. Ano dinâmico; perfis sociais só quando confirmados.</p></div><div class="doc-asset-notice">Menu modal: foco contido, fundo sem rolagem, aria-expanded, fechamento por Escape, botão e seleção de âncora.</div></div></div>'''
out+=sheet('05','Components / Navigation',c)

c=header('06','Composição da página.','Os componentes formam uma landing page responsiva. A prévia pode ser inspecionada em diferentes larguras.')
c+='''<div class="doc-toolbar"><button data-width="1440" aria-pressed="true">Desktop · 1440</button><button data-width="768" aria-pressed="false">Tablet · 768</button><button data-width="390" aria-pressed="false">Mobile · 390</button><a class="doc-download" href="landing.html" target="_blank" rel="noopener">Abrir protótipo completo ↗</a><span class="doc-dim">Prévia com rolagem interna</span></div><div class="frame-stage" id="frame-stage"><div class="frame-inner" id="frame-inner"><iframe src="landing.html" title="Protótipo responsivo da Cabanha Grandi" width="1440" height="950" id="preview-frame"></iframe></div></div><img class="preview-print" src="assets/design-reference.png" alt="Prancha original da direção Dorper em Foco"><p class="doc-note">Prancha de referência ilustrativa. A especificação textual prevalece sobre textos, medidas e estados desenhados na imagem.</p>'''
out+=sheet('06','Patterns / Responsive page',c)

c=header('06b','Seções que se conectam.','Uma estrutura editorial com comportamento definido, conteúdo validável e espaço para fotografias reais.')
c+='<div class="doc-grid"><div class="doc-panel">'+component('Hero')+'<h3>Fotografia, mensagem e ação</h3><p>H1 80/84 desktop; 44/48 mobile. Largura de texto até 560px. Mínimo 640px desktop; altura automática no mobile. Overlay vinho mantém a legibilidade.</p><p class="doc-note">CTA primário → #animais. Secundário → #historia. Foto preserva cabeça e orelhas no recorte.</p></div><div class="doc-panel">'+component('StorySection')+'<h3>Texto + imagem em 6/6</h3><p>Gap 48px desktop, 24px mobile. Empilhar texto antes da imagem. Sem criar retratos fictícios dos familiares.</p><p class="doc-note">Raízes em Torricella del Pizzo, Nova Prata e iniciativa de Ênio e Anderson Grandi. Copy sujeita à revisão.</p></div><div class="doc-panel">'+component('Gallery')+'<h3>2–5 registros da propriedade</h3><div class="doc-grid three" style="gap:12px"><div class="cg-placeholder" style="min-height:110px;padding:8px">4:3</div><div class="cg-placeholder" style="min-height:110px;padding:8px">4:3</div><div class="cg-placeholder" style="min-height:110px;padding:8px">4:3</div></div><p class="doc-note">3 / 2 / 1 colunas. Sem carrossel na base. Alt e legenda por imagem; fotos reais ainda pendentes.</p></div><div class="doc-panel">'+component('ContactBand')+'<div style="background:#770D17;color:white;padding:24px;border-radius:4px"><h3 class="cg-h3" style="font-size:32px">Vamos conversar?</h3><p style="color:white;margin-bottom:16px">Conheça a cabanha e os animais.</p>'+button('Conversar no WhatsApp','inverse')+'</div><p class="doc-note">Exemplo de componente. Sem número confirmado, o protótipo omite o link WhatsApp e informa a pendência.</p></div></div><div class="doc-rule"></div>'
c+=table(['Ordem','Seção / âncora','Composição'],[['01','Hero / #inicio','Foto + texto + 2 ações'],['02','História / #historia','Texto 6 colunas + imagem 6 colunas'],['03','Propriedade / #propriedade','Galeria responsiva'],['04','Criação / #criacao','Apresentação da raça / fotografia'],['05','Animais / #animais','Estado vazio ou até 6 cards reais'],['06','Contato / #contato','Texto + canal oficial'],['07','Rodapé','Marca, âncoras e localidade']])
out+=sheet('06b','Patterns / Section anatomy',c)

c=header('07','Pronto para orientar o código.','Os arquivos descrevem o mesmo sistema visual em formatos legíveis para pessoas e ferramentas. Abra o pacote extraído para preservar imagens e fontes.')
c+=table(['Arquivo','Função'],[['index.html','Documento visual navegável e inspetor de componentes.'],['tokens.json + tokens.css','123 tokens tipados; 97 custom properties CSS derivadas.'],['components.css','Estilos reutilizáveis dos exemplos e do protótipo.'],['components.schema.json','Manifesto de 14 componentes: props, variantes, estados e regras. Não é um JSON Schema de validação.'],['contracts.ts','Contratos TypeScript independentes de framework.'],['HANDOFF.md','Especificação textual, comportamento e critérios de revisão.'],['landing.html','Protótipo HTML de referência; conteúdo e contatos pendentes.']])
c+='<div class="doc-grid" style="margin-top:32px"><div class="doc-panel"><h3>Instrução para uma ferramenta de código</h3><textarea readonly class="doc-prompt" id="implementation-prompt">Implemente a landing page Cabanha Grandi seguindo HANDOFF.md. Use tokens.json como fonte de valores, tokens.css e components.css como referência de estilo, components.schema.json para variantes/estados e contracts.ts para tipos. Preserve a direção Dorper em Foco. Não invente contatos, animais ou claims. Mantenha catálogo vazio até haver dados reais. Valide 360, 390, 768, 1024 e 1440px, navegação por teclado e contraste.</textarea><button class="cg-button no-print" id="copy-prompt" style="margin-top:16px">Copiar instrução</button></div><div class="doc-panel"><h3>O que falta para produção</h3><p>Logo original, fotografias autorizadas, texto revisado, contatos oficiais e dados dos animais.</p><p class="doc-note">Este pacote é um documento HTML/CSS e uma especificação técnica. Não é um arquivo .fig nativo, nem uma aplicação React pronta. Os contratos servem de base para implementação.</p><div class="cg-stack no-print" style="gap:8px;margin-top:24px"><a class="doc-download" href="tokens.json" download>Baixar tokens.json ↓</a><a class="doc-download" href="components.schema.json" download>Baixar manifesto ↓</a><a class="doc-download" href="contracts.ts" download>Baixar contratos TypeScript ↓</a><a class="doc-download" href="HANDOFF.md" download>Baixar handoff ↓</a></div></div></div><p class="doc-note">Fontes locais: Cormorant Garamond + DM Sans, distribuídas com licença OFL. O documento funciona offline após extrair o ZIP.</p>'
out+=sheet('07','Handoff / Code contract',c)
out+='''</main><aside class="inspector" id="inspector" hidden aria-label="Propriedades do componente"><button class="inspector-close" id="close-inspector" aria-label="Fechar inspetor">×</button><div id="inspector-content"></div></aside><div class="toast" id="toast" role="status" aria-live="polite"></div>
<dialog class="cg-menu" id="demo-menu" aria-labelledby="demo-menu-title"><div class="cg-menu__top"><h2 class="cg-h3" id="demo-menu-title">Navegação · demonstração</h2><button class="cg-icon-button" id="close-demo-menu" aria-label="Fechar menu">×</button></div><nav aria-label="Menu de demonstração"><a href="#s00">Início</a><a href="#s04">Animais / componentes</a><a href="#s06">Página completa</a><a href="#s07">Desenvolvimento</a></nav></dialog><script src="catalog-data.js"></script><script src="document.js"></script></body></html>'''
(ROOT/'index.html').write_text(out)
print('index.html + catalog-data.js gerados; 14 componentes no manifesto')
